        return false;
    }

    if (hasActiveTargetRun(scm, ctx.configFile, ctx.ticketKey, ctx.workflowFile, aiTarget.owner, aiTarget.repo)) {
        return false;
    }

    scm.triggerWorkflow(
        aiTarget.owner,
